import{_ as i,o as e,c as s,a2 as n}from"./chunks/framework.CuEaBji2.js";const k=JSON.parse('{"title":"独立 Agent 热升级","description":"","frontmatter":{},"headers":[],"relativePath":"operations/agent-hot-upgrade.md","filePath":"operations/agent-hot-upgrade.md","lastUpdated":1789799472000}'),t={name:"operations/agent-hot-upgrade.md"};function l(r,a,p,o,d,h){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="独立-agent-热升级" tabindex="-1">独立 Agent 热升级 <a class="header-anchor" href="#独立-agent-热升级" aria-label="Permalink to &quot;独立 Agent 热升级&quot;">​</a></h1><p><code>hot_upgrade</code> 只适用于声明自更新能力的独立 <code>nre-agent</code>。Embedded local Agent 与 control-plane 容器本身不通过此路径热升级。当前完整 listener/packet FD handoff 支持平台是：</p><ul><li><code>linux/amd64</code>（version policy platform 写 <code>linux-amd64</code>）</li><li><code>linux/arm64</code>（version policy platform 写 <code>linux-arm64</code>）</li></ul><p>这条二进制热升级路径不替代旧 Relay 认证迁移。首次切换到内部 PKI mTLS 时仍需维护窗口、bound re-enrollment、稳定 Agent/listener 关联核对和显式 activation；见<a href="./internal-pki">内部 PKI 升级与运维</a>。控制面的 revision/upgrade 请求始终使用既有 token 控制协议，不新增 mTLS 控制端口。</p><p>非 Linux、其他 architecture 或未声明对应 package/capability 的 Agent 会在 preflight 显式拒绝，不会降级为有停机的进程替换。</p><h2 id="package-与-generation" tabindex="-1">Package 与 generation <a class="header-anchor" href="#package-与-generation" aria-label="Permalink to &quot;Package 与 generation&quot;">​</a></h2><p>默认镜像在 public Agent assets 目录随附受支持平台的 <code>nre-agent-&lt;platform&gt;</code>。Version policy 设置目标版本；<code>packages</code> 留空时，control plane 按 Agent 报告的平台选择 bundled binary，并生成包含 URL、SHA-256、platform、filename、size 的完整 <code>version_package_meta</code>：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;channel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;desired_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;packages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>如果使用自建分发流程，送达 Agent snapshot 的 package metadata 仍必须同时提供安全 basename <code>filename</code>、正 <code>size</code>、64 位十六进制 SHA-256 和精确 platform；缺一项或 platform 不匹配会在 preflight 拒绝。不要只用 URL/SHA 假定可以热升级。</p><p>Agent 把 package 下载到 digest 命名的 immutable 目录，校验 size/SHA-256 和可执行文件，写入 current/previous pointer 后启动 child。目标二进制和目标 snapshot 绑定同一 revision/generation identity，child 必须完成 snapshot prepare、listener/packet authority 接管和 readiness 才能激活。</p><p>Package 下载、校验和 immutable 暂存由 Agent 进程内的单飞协调器执行，不占用周期 heartbeat，也不计入 revision apply lease。下载很慢时，Agent 仍按既有周期上报当前运行 package、当前 revision 和 apply 状态；控制面因而继续更新最近心跳并按原有三倍心跳阈值判断真实在线/离线。暂存中的 package 在节点状态中保持 <code>pending</code>，不能视为目标版本或 revision 已应用。</p><p>只有 package 已 verified-ready，且后续 heartbeat 仍指向相同 immutable package 与目标版本时，Agent 才重新拉取当前 revision lease，并进入既有 Start、Activate、apply 和 report 流程。下载失败、校验失败、目标变化或 Agent shutdown 会取消或结束暂存 attempt，旧 binary、旧 revision 和现有 HTTP/L4 数据面继续服务；下一次同步沿用既有重试规则，不会把暂存失败报告成 applied。URL 只是获取位置，同一 platform/SHA-256/size/filename identity 不会因 URL 或版本展示值变化而并发重复下载。</p><p>升级期间：</p><ol><li>Parent 继续服务旧 generation，并把新 stream/packet authority 有序交给 child。</li><li>Child ready 后新连接进入目标 generation；旧 TCP 会话与 UDP/QUIC association 仍由原 owner 服务。</li><li>Parent 按该 revision 固化的 drain timeout 排空；authority journal 记录 launch、activation 和 transfer checkpoint。</li><li>接管完成后 current pointer 保持目标 binary，previous pointer 保留前一版本。最初的 systemd 主进程保留为监督进程，后续业务进程在完成下一次交接后退出；核对运行包 SHA 时应查看 authority journal 指向的业务进程，而不是只查看 systemd MainPID。</li></ol><p>Child prepare、activation、authority transfer 或 identity 校验失败时，parent 保持或恢复 authority 和 last-known-good generation，失败 child 被终止，current pointer 恢复 previous。失败不会把未 ready generation 报为 applied。</p><h2 id="更新包自动回收" tabindex="-1">更新包自动回收 <a class="header-anchor" href="#更新包自动回收" aria-label="Permalink to &quot;更新包自动回收&quot;">​</a></h2><p>业务进程启动并取得控制权后，以及每次下载或复用升级包前，Agent 自动检查 <code>updates/packages/</code>。无引用且目录修改时间超过 24 小时的完整历史包会被删除。以下包始终保留：</p><ul><li><code>updates/state/current.json</code> 和 <code>previous.json</code> 引用的当前包、回滚包。</li><li>Linux <code>/proc</code> 中仍在运行的业务进程、排空进程或监督进程所用的包。</li><li>本进程已暂存的升级包，以及本次请求准备下载或复用的目标包。</li></ul><p>最近 24 小时的包保留到后续启动或升级时再检查。首次安装尚无 current pointer、指针损坏或无法完整读取进程信息时，会跳过回收；清理错误记录到 Agent 日志，不阻断启动或升级。回收只删除经过校验的包内 <code>nre-agent</code>、<code>manifest.json</code> 和空目录，不递归删除未知文件或跟随符号链接，也不处理日志、证书和配置数据。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>确认 Agent 列表中的 runtime platform/arch、当前 package SHA-256、capabilities 和最近心跳。</li><li>确认 control plane 的 public assets 中存在目标平台 binary，并在 heartbeat/snapshot 中核对完整 <code>version_package_meta</code> 的 SHA-256、filename 和 size。</li><li>将目标 Agent 的 <code>desired_version</code> 更新到新版本；该写入返回 202 operation，不是同步完成。</li><li>跟踪 operation <code>status_url</code>、Agent revision、<code>nre_hot_restart_upgrade_total</code> / <code>nre_agent_hot_restart_upgrade_total</code> 和 correlation 日志。</li><li>只有 revision 为 applied 且 drain 已 drained/forced 后，才把升级视为稳定完成。</li></ol><p>异常处理：</p><ul><li><code>unsupported</code>：核对 Agent 报告的平台是否为 Linux amd64/arm64，且 version policy 有精确 platform package；不要强制使用其他平台 binary。</li><li>digest/size mismatch：撤下损坏 artifact，发布新 immutable URL/digest；不要覆盖已有 digest 目录。</li><li>下载长时间未完成：先确认节点最近心跳仍持续推进且 package 状态为 <code>pending</code>；不要因 apply deadline 尚未开始而手工标记失败。若最近心跳停止，则按普通 Agent 网络/进程失联排查，控制面仍会在原有离线阈值后标记 offline。</li><li>child readiness/authority failure：保留日志中的 revision/generation/attempt，确认 parent 仍服务旧 generation，再显式 retry failed revision。</li><li>目标配置本身有误：使用 revision rollback，把 last-known-good snapshot 复制成新的 desired revision；不要手工改历史记录。</li></ul><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./internal/hotrestart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./internal/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./internal/platform</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generation-soak</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TestGenerationMatrix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Linux 发布验证还应检查真实 process/packet matrix：新连接无由升级导致的拒绝，旧会话保持原路径，重复升级后 child/parent 进程、FD、goroutine 和 draining generation 均回到有界基线。</p>`,26)])])}const g=i(t,[["render",l]]);export{k as __pageData,g as default};
